  "param.retarget.foot_pin": "Pin",
  "param.retarget.foot_pin.help": "ball: the ball of the foot at contact, ankle: the ankle only.",
  "param.retarget.loop_blend": "Loop seam, frames",
  "param.retarget.loop_blend.help": "Frames of smooth loop closing.",
  "param.retarget.facing": "Body facing",
  "param.retarget.facing.help": "rest: remove the average rotation around the vertical of facing_bone (an archer's ~45° side stance faces as in rest); keep: as in the clip. Can also be set per clip.",
  "param.retarget.facing_bone": "Facing bone",
  "param.retarget.facing_bone.help": "Bone used to measure the rotation for facing rest (e.g. Spine2); empty: Hips. Can also be set per clip.",
  "param.retarget.hips_drop": "Hips drop",
  "param.retarget.hips_drop.help": "Fraction of the hips drop below rest that is kept: 0: the hips never go below rest, IK straightens the legs (a robe hem on the floor in a crouching idle); death needs 1. Can also be set per clip.",
  "param.retarget.hips_height_m": "Target hips height, m",
  "param.retarget.hips_height_m.help": "Explicit hip joint height for the root scale; empty: measured (a guess under a robe).",
  "param.retarget.floor": "Floor for leg IK",
  "param.retarget.floor.help": "Ankle and ball IK targets stay no lower than their height in the target rest pose.",
  "param.retarget.hand_floor": "Floor for hands",
